__d(function(n,t,i,o,d,e,l){d.exports={terms:{title:"\uc774\uc6a9\uc57d\uad00",body:"## \uc81c1\uc870 \ubaa9\uc801\n\n\uc774 \uc57d\uad00\uc740 [\uc6b4\uc601\uc790 \uc774\ub984](\uc774\ud558 \u2018\uc6b4\uc601\uc790\u2019)\uc774 \uc81c\uacf5\ud558\ub294 [\uc5b4\ud50c \uc774\ub984](\uc774\ud558 \u2018\uc5b4\ud50c\u2019)\uc744 \uc774\uc6a9\ud558\ub294 \ub370 \ud544\uc694\ud55c \uc870\uac74\uacfc \uc808\ucc28, \uc6b4\uc601\uc790\uc640 \uc774\uc6a9\uc790\uc758 \uad8c\ub9ac\uc640 \uc758\ubb34\ub97c \uc815\ud569\ub2c8\ub2e4.\n\n## \uc81c2\uc870 \uc11c\ube44\uc2a4\uc758 \ub0b4\uc6a9\n\n1. \uc5b4\ud50c\uc740 \uc0ac\uc8fc, \ubcc4\uc790\ub9ac, \ud608\uc561\ud615, \uc131\uaca9 \uc720\ud615\uc744 \uc5ee\uc5b4 \ud55c \uc0ac\ub78c\uc758 \uc131\ud5a5\uacfc \ub450 \uc0ac\ub78c\uc758 \uad81\ud569\uc744 \ud480\uc774\ud569\ub2c8\ub2e4.\n2. \ud480\uc774\uc758 \uacc4\uc0b0\uc740 \uc815\ud574\uc9c4 \uaddc\uce59\uc73c\ub85c \ud558\uace0, \ud480\uc774 \uae00\uc758 \uc77c\ubd80\ub294 \uc0dd\uc131\ud615 \uc778\uacf5\uc9c0\ub2a5\uc774 \uc501\ub2c8\ub2e4. \uc778\uacf5\uc9c0\ub2a5\uc774 \uc4f4 \uae00\uc5d0\ub294 \uadf8 \uc0ac\uc2e4\uc744 \ud45c\uc2dc\ud569\ub2c8\ub2e4.\n3. \uc5b4\ud50c\uc774 \uc4f0\ub294 \uc131\uaca9 \uc720\ud615\uc740 \uc774\uc6a9\uc790\uac00 \uc774\ubbf8 \uc544\ub294 \uc720\ud615\uc744 \uace0\ub974\ub294 \ubc29\uc2dd\uc774\uba70, \uacf5\uc2dd \uc131\uaca9 \uac80\uc0ac\uac00 \uc544\ub2d9\ub2c8\ub2e4.\n\n## \uc81c3\uc870 \ud480\uc774\uc758 \uc131\uaca9\n\n1. \ud480\uc774\ub294 \uc7ac\ubbf8\uc640 \uc790\uae30 \uc774\ud574\ub97c \uc704\ud55c \ucc38\uace0 \uc790\ub8cc\uc785\ub2c8\ub2e4.\n2. \uc0ac\uc8fc, \ubcc4\uc790\ub9ac, \ud608\uc561\ud615, \uc131\uaca9 \uc720\ud615\uc73c\ub85c \uc0ac\ub78c \uc0ac\uc774\ub97c \ub9de\ud78c\ub2e4\ub294 \uacfc\ud559\uc801 \uadfc\uac70\ub294 \ubc1d\ud600\uc9c0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uc6b4\uc601\uc790\ub294 \ud480\uc774\uac00 \uc815\ud655\ud558\ub2e4\uac70\ub098 \uc55e\uc77c\uc744 \ub9de\ud78c\ub2e4\uace0 \ubcf4\uc99d\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n3. \ud480\uc774\ub97c \uc758\ud559, \ubc95\ub960, \ub3c8\uacfc \ud22c\uc790, \uacb0\ud63c\uacfc \uc774\ubcc4 \uac19\uc740 \uc911\uc694\ud55c \uacb0\uc815\uc758 \uadfc\uac70\ub85c \uc4f0\uc9c0 \ub9d0\uc544 \uc8fc\uc138\uc694.\n\n## \uc81c4\uc870 \uc774\uc6a9 \uc870\uac74\n\n1. \uc5b4\ud50c\uc740 \ub9cc 14\uc138 \uc774\uc0c1\ub9cc \uc774\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n2. 1\ub2e8\uacc4\uc5d0\uc11c\ub294 \uac00\uc785 \uc5c6\uc774 \uc774\uc6a9\ud558\uba70, \uc774\uc6a9\uc790\uac00 \ub123\uc740 \uc815\ubcf4\ub294 \uc774\uc6a9\uc790\uc758 \uae30\uae30\uc5d0 \uc800\uc7a5\ub429\ub2c8\ub2e4. \uae30\uae30\ub97c \ubc14\uafb8\uac70\ub098 \uae30\ub85d\uc744 \uc9c0\uc6b0\uba74 \uc815\ubcf4\uc640 \ud480\uc774 \uae30\ub85d\uc774 \uc0ac\ub77c\uc9d1\ub2c8\ub2e4.\n3. [3\ub2e8\uacc4\ubd80\ud130] \uac00\uc785\uacfc \ub85c\uadf8\uc778, \ud0c8\ud1f4\uc5d0 \uad00\ud55c \uc870\ud56d\n\n## \uc81c5\uc870 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc815\ubcf4\ub97c \ub123\uc744 \ub54c\n\n1. \uc774\uc6a9\uc790\ub294 \uad81\ud569\uc744 \ubcf4\uae30 \uc704\ud574 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc0dd\ub144\uc6d4\uc77c \ub4f1\uc744 \ub123\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub54c \uc774\uc6a9\uc790\ub294 \uadf8 \uc0ac\ub78c\uc5d0\uac8c \uc54c\ub9ac\uace0 \ub123\uc73c\uba70, \uc774\ub984 \ub300\uc2e0 \ubcc4\uba85\uc744 \uc501\ub2c8\ub2e4.\n2. \uc774\uc6a9\uc790\ub294 \ub9cc 14\uc138 \ubbf8\ub9cc\uc778 \uc0ac\ub78c\uc758 \uc815\ubcf4\ub97c \ub123\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.\n3. \uc774\uc6a9\uc790\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc815\ubcf4\ub97c \uadf8 \uc0ac\ub78c\uc744 \uad34\ub86d\ud788\uac70\ub098 \uae4e\uc544\ub0b4\ub9ac\ub294 \ub370 \uc4f0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n4. \uc774\uc6a9\uc790\uac00 \ub123\uc740 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc815\ubcf4\uc5d0 \uad00\ud55c \ucc45\uc784\uc740 \uadf8 \uc815\ubcf4\ub97c \ub123\uc740 \uc774\uc6a9\uc790\uc5d0\uac8c \uc788\uc2b5\ub2c8\ub2e4.\n5. \uc790\uc2e0\uc758 \uc815\ubcf4\uac00 \ub0a8\uc5d0\uac8c \ub123\uc5b4\uc84c\ub2e4\uace0 \uc0dd\uac01\ud558\ub294 \uc0ac\ub78c\uc740 \uc6b4\uc601\uc790\uc5d0\uac8c \ubb38\uc758\ud560 \uc218 \uc788\uc73c\uba70, \uc6b4\uc601\uc790\ub294 \ucc98\ub9ac\ubc29\uce68 \uc81c6\uc870\uc5d0 \ub530\ub77c \uc548\ub0b4\ud569\ub2c8\ub2e4.\n6. [2\ub2e8\uacc4\ubd80\ud130] \ucd08\ub300\ub97c \ubc1b\uc740 \uc0ac\ub78c\uc740 \ubcf4\ub0b8 \uc0ac\ub78c\uc774 \ub123\uc5b4 \ub454 \uc790\uc2e0\uc758 \uc815\ubcf4\ub97c \uc9c0\uc6b8 \uc218 \uc788\uace0, \uc9c1\uc811 \ub123\uc740 \uc815\ubcf4\uac00 \uc55e\uc120 \uc815\ubcf4\ub97c \ub300\uc2e0\ud569\ub2c8\ub2e4.\n\n## \uc81c6\uc870 \uae08\uc9c0 \ud589\uc704\n\n\uc774\uc6a9\uc790\ub294 \ub2e4\uc74c \ud589\uc704\ub97c \ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n1. \ub2e4\ub978 \uc0ac\ub78c\uc778 \ucc99\ud558\uac70\ub098, \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc815\ubcf4\ub97c \uadf8 \uc0ac\ub78c\uc758 \ub73b\uc5d0 \ubc18\ud574 \uc4f0\ub294 \ud589\uc704\n2. \ud480\uc774\ub098 \uacf5\uc720 \uadf8\ub9bc\uc744 \ub2e4\ub978 \uc0ac\ub78c\uc744 \ub180\ub9ac\uac70\ub098 \ucc28\ubcc4\ud558\ub294 \ub370 \uc4f0\ub294 \ud589\uc704\n3. \uc5b4\ud50c\uc758 \uacc4\uc0b0\uc774\ub098 \uc11c\ubc84\uc5d0 \ube44\uc815\uc0c1\uc801\uc73c\ub85c \uc811\uadfc\ud558\uac70\ub098, \uc790\ub3d9\ud654\ub41c \ubc29\ubc95\uc73c\ub85c \ub300\ub7c9\uc758 \uc694\uccad\uc744 \ubcf4\ub0b4\ub294 \ud589\uc704\n4. \ud480\uc774 \uae00\uc744 \uc6b4\uc601\uc790\uc758 \ud5c8\ub77d \uc5c6\uc774 \ubaa8\uc544 \ub2e4\ub978 \uc11c\ube44\uc2a4\ub098 \ud310\ub9e4\uc5d0 \uc4f0\ub294 \ud589\uc704\n\n## \uc81c7\uc870 \ud480\uc774 \uc2e0\uace0\n\n1. \uc774\uc6a9\uc790\ub294 \ud480\uc774 \uae00\uc774 \ubd88\ucf8c\ud558\uac70\ub098 \uc798\ubabb\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ub418\uba74 \uc5b4\ud50c \uc548\uc758 \uc2e0\uace0 \ub2e8\ucd94\ub098 \ubb38\uc758 \ucc3d\uad6c\ub85c \uc54c\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n2. \uc6b4\uc601\uc790\ub294 \uc2e0\uace0\ub97c \ud655\uc778\ud558\uace0, \ud544\uc694\ud558\uba74 \ud574\ub2f9 \uae00\uc744 \uace0\uce58\uac70\ub098 \ub2e4\uc2dc \uc501\ub2c8\ub2e4.\n\n## \uc81c8\uc870 \uc11c\ube44\uc2a4\uc758 \ubcc0\uacbd\uacfc \uc911\ub2e8\n\n1. \uc6b4\uc601\uc790\ub294 \ud480\uc774\uc758 \uaddc\uce59\uacfc \uae00\uc744 \uace0\uce60 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ubbf8 \ubcf8 \ud480\uc774\ub294 \ubcf8 \uadf8\ub300\ub85c \ubcf4\uad00\ub429\ub2c8\ub2e4.\n2. \uc6b4\uc601\uc790\ub294 \uc11c\ubc84 \uc810\uac80, \uc778\uacf5\uc9c0\ub2a5 \uc0ac\uc5c5\uc790\uc758 \uc7a5\uc560 \ub4f1\uc73c\ub85c \uc11c\ube44\uc2a4\uc758 \uc77c\ubd80(\uc608: \ucd1d\ud3c9)\ub97c \uc7a0\uc2dc \uc81c\uacf5\ud558\uc9c0 \ubabb\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n3. \uc11c\ube44\uc2a4\ub97c \ub05d\ub0bc \ub54c\ub294 [30\uc77c](\uac00\uc548) \uc804\uc5d0 \uc5b4\ud50c \uc548\uc5d0 \uc54c\ub9bd\ub2c8\ub2e4.\n\n## \uc81c9\uc870 \uc9c0\uc2dd\uc7ac\uc0b0\n\n1. \uc5b4\ud50c\uc758 \ud480\uc774 \uae00, \uc774\ub984, \uadf8\ub9bc\uc758 \uad8c\ub9ac\ub294 \uc6b4\uc601\uc790\uc5d0\uac8c \uc788\uc2b5\ub2c8\ub2e4.\n2. \uc774\uc6a9\uc790\ub294 \uc790\uc2e0\uc774 \ubcf8 \ud480\uc774\ub97c \uac1c\uc778\uc801\uc73c\ub85c \uc800\uc7a5\ud558\uac70\ub098 \uadf8\ub9bc\uc73c\ub85c \uacf5\uc720\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n## \uc81c10\uc870 \ucc45\uc784\uc758 \ud55c\uacc4\n\n1. \uc6b4\uc601\uc790\ub294 \uc81c3\uc870\uc5d0 \ub530\ub77c \ud480\uc774\uc758 \uc815\ud655\uc131\uc744 \ubcf4\uc99d\ud558\uc9c0 \uc54a\uc73c\uba70, \uc774\uc6a9\uc790\uac00 \ud480\uc774\ub97c \uadfc\uac70\ub85c \ub0b4\ub9b0 \uacb0\uc815\uc758 \uacb0\uacfc\uc5d0 \ucc45\uc784\uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uc6b4\uc601\uc790\uc758 \uace0\uc758\ub098 \uc911\ub300\ud55c \uacfc\uc2e4\ub85c \uc0dd\uae34 \uc190\ud574\ub294 \uc608\uc678\ub85c \ud569\ub2c8\ub2e4.\n2. \uae30\uae30\uc5d0 \uc800\uc7a5\ub41c \uc815\ubcf4\uac00 \uae30\uae30 \ubd84\uc2e4, \uae30\ub85d \uc0ad\uc81c \ub4f1\uc73c\ub85c \uc0ac\ub77c\uc9c4 \uacbd\uc6b0 \uc6b4\uc601\uc790\ub294 \uc774\ub97c \ub418\uc0b4\ub9b4 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.\n\n## \uc81c11\uc870 \uc720\ub8cc \uc11c\ube44\uc2a4\n\n[4\ub2e8\uacc4\ubd80\ud130] \uae4a\uc740 \ud480\uc774\uc758 \uad6c\ub9e4, \uac12, \ud55c \uc0ac\ub78c\uc774 \uc0ac\uba74 \ub458 \ub2e4 \ubcf4\ub294 \uac83\uacfc \ud658\ubd88 \ub300\uc0c1, \uc5f4\ub78c \ub4a4 \uccad\uc57d \ucca0\ud68c \uc81c\ud55c, \ubbf8\uc131\ub144\uc790 \uacb0\uc81c \ucde8\uc18c\uc5d0 \uad00\ud55c \uc870\ud56d\n\n## \uc81c12\uc870 \uc54c\ub9bc\n\n[3\ub2e8\uacc4\ubd80\ud130] \uc11c\ube44\uc2a4 \uc54c\ub9bc\uacfc \uad11\uace0\uc131 \uc54c\ub9bc, \ubc1b\ub294 \uc2dc\uac01, \ub044\ub294 \ubc29\ubc95\uc5d0 \uad00\ud55c \uc870\ud56d\n\n## \uc81c13\uc870 \uc57d\uad00\uc758 \ubcc0\uacbd\n\n\uc6b4\uc601\uc790\ub294 \uc57d\uad00\uc744 \ubc14\uafc0 \ub54c \uc2dc\ud589 7\uc77c \uc804\ubd80\ud130(\uc774\uc6a9\uc790\uc5d0\uac8c \ubd88\ub9ac\ud55c \ubcc0\uacbd\uc740 30\uc77c \uc804\ubd80\ud130) \uc5b4\ud50c \uc548\uc5d0 \uc54c\ub9bd\ub2c8\ub2e4.\n\n## \uc81c14\uc870 \uc900\uac70\ubc95\uacfc \ubd84\uc7c1\n\n\uc774 \uc57d\uad00\uc740 \ub300\ud55c\ubbfc\uad6d \ubc95\uc744 \ub530\ub974\uba70, \ubd84\uc7c1\uc740 \ubbfc\uc0ac\uc18c\uc1a1\ubc95\uc5d0 \ub530\ub978 \uad00\ud560 \ubc95\uc6d0\uc5d0\uc11c \ud574\uacb0\ud569\ub2c8\ub2e4.\n\n## \ubd80\uce59\n\n\uc774 \uc57d\uad00\uc740 [\uc2dc\ud589\uc77c]\ubd80\ud130 \uc801\uc6a9\ud569\ub2c8\ub2e4.\n\n## \ubb38\uc758\n\n- \uc6b4\uc601\uc790: [\uc6b4\uc601\uc790 \uc774\ub984]\n- \uc5f0\ub77d\ucc98: [\uc774\uba54\uc77c]\n- [4\ub2e8\uacc4\ubd80\ud130] \uc0ac\uc5c5\uc790 \uc815\ubcf4: \uc0c1\ud638, \ub300\ud45c\uc790, \uc0ac\uc5c5\uc790\ub4f1\ub85d\ubc88\ud638, \ud1b5\uc2e0\ud310\ub9e4\uc5c5 \uc2e0\uace0\ubc88\ud638, \uc8fc\uc18c"},privacy:{title:"\uac1c\uc778\uc815\ubcf4 \ucc98\ub9ac\ubc29\uce68",body:"[\uc5b4\ud50c \uc774\ub984](\uc774\ud558 \u2018\uc5b4\ud50c\u2019)\uc744 \uc6b4\uc601\ud558\ub294 [\uc6b4\uc601\uc790 \uc774\ub984](\uc774\ud558 \u2018\uc6b4\uc601\uc790\u2019)\uc740 \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ubc95\uc5d0 \ub530\ub77c \uc774\uc6a9\uc790\uc758 \uac1c\uc778\uc815\ubcf4\ub97c \ubcf4\ud638\ud558\uace0, \uc774\uc640 \uad00\ub828\ud55c \uace0\ucda9\uc744 \ube60\ub974\uac8c \ucc98\ub9ac\ud558\uae30 \uc704\ud574 \ub2e4\uc74c\uacfc \uac19\uc774 \ucc98\ub9ac\ubc29\uce68\uc744 \ub461\ub2c8\ub2e4.\n\n## \uc81c1\uc870 \ucc98\ub9ac\ud558\ub294 \uac1c\uc778\uc815\ubcf4\uc640 \ucc98\ub9ac\ud558\ub294 \uacf3\n\n\uc5b4\ud50c\uc740 \ud480\uc774\ub97c \uacc4\uc0b0\ud558\ub294 \ub370 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uc774\uc6a9\uc790\uc758 \uae30\uae30 \uc548\uc5d0\uc11c\ub9cc \ucc98\ub9ac\ud558\ub294 \uac83\uc744 \uc6d0\uce59\uc73c\ub85c \ud569\ub2c8\ub2e4.\n\n| \uc815\ubcf4 | \ucc98\ub9ac\ud558\ub294 \uacf3 | \ubaa9\uc801 |\n|---|---|---|\n| \ubcc4\uba85, \uc0dd\ub144\uc6d4\uc77c(\uc591\ub825\xb7\uc74c\ub825, \uc724\ub2ec), \ud0dc\uc5b4\ub09c \uc2dc\uac01, \uc131\ubcc4, \ud608\uc561\ud615, \uc131\uaca9 \uc720\ud615 | \uc774\uc6a9\uc790\uc758 \uae30\uae30\uc5d0\ub9cc \uc800\uc7a5 | \uc0ac\uc8fc, \ubcc4\uc790\ub9ac, \uad81\ud569 \ud480\uc774\uc758 \uacc4\uc0b0 |\n| \uc774\uc6a9\uc790\uac00 \uc9c1\uc811 \ub123\uc740 \uc0c1\ub300\uc758 \ubcc4\uba85\uacfc \uc704 \uc815\ubcf4 | \uc774\uc6a9\uc790\uc758 \uae30\uae30\uc5d0\ub9cc \uc800\uc7a5 | \uad81\ud569 \ud480\uc774\uc758 \uacc4\uc0b0 |\n| \uacc4\uc0b0 \uacb0\uacfc(\uc601\uc5ed\ub9c8\ub2e4\uc758 \ud310\uc815 \uac12, \uad00\uacc4 \uc720\ud615 \uc774\ub984, \ubbf8\ub9ac \uc4f4 \uae00\uc758 \ubc88\ud638) | \uc6b4\uc601\uc790\uc758 \uc11c\ubc84, \uc778\uacf5\uc9c0\ub2a5 \uc0ac\uc5c5\uc790 | \ucd1d\ud3c9 \uae00\uc758 \uc791\uc131\uacfc \uc800\uc7a5 |\n| \uae30\uae30\ub9c8\ub2e4 \ub9cc\ub4dc\ub294 \uc784\uc758 \ubc88\ud638 | \uc6b4\uc601\uc790\uc758 \uc11c\ubc84 | \ud558\ub8e8 \uc774\uc6a9 \ud69f\uc218\uc758 \uacc4\uc0b0 |\n| [\uc11c\ubc84\uac00 \uc0dd\uae38 \ub54c\ubd80\ud130] \uadf8\ub0a0 \uc5f0 \ud480\uc774\uc758 \uc774\ub984(\uc608: \u2018\uc5f0\uc778 \xb7 \ub300\ud654\u2019)\uacfc \ub05d\uae4c\uc9c0 \ubd24\ub294\uc9c0 | \uc6b4\uc601\uc790\uc758 \uc11c\ubc84 | \ub9ce\uc774 \ubcf8 \ud480\uc774 \uc21c\uc704. \uc704 \uc784\uc758 \ubc88\ud638\uc640 \ud568\uaed8 \ubc1b\uace0, \uc774\uc6a9\uc790\ub294 \u2018\ub354 \ubcf4\uae30\u2019\uc5d0\uc11c \ubcf4\ub0b4\uae30\ub97c \ub04c \uc218 \uc788\uc74c |\n\n[\uc5b4\ud50c \ub2e8\uacc4\ubd80\ud130] \uc774\uc6a9\uc790\uac00 \ud734\ub300\ud3f0 \uc790\uccb4\uc758 \ubc31\uc5c5(\uad6c\uae00 \ubc31\uc5c5, iCloud \ubc31\uc5c5 \ub4f1)\uc744 \ucf1c \ub450\uc5c8\ub2e4\uba74, \uae30\uae30\uc5d0 \uc800\uc7a5\ub41c \uc704 \uc815\ubcf4\uac00 \uadf8 \ubc31\uc5c5\uc5d0 \ud568\uaed8 \ub2f4\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \ubc31\uc5c5\uc740 \uc774\uc6a9\uc790\uc758 \uacc4\uc815\uc5d0 \ubcf4\uad00\ub418\uba70, \uc6b4\uc601\uc790\ub294 \uadf8 \ub0b4\uc6a9\uc744 \ubc1b\uac70\ub098 \ubcfc \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ubc31\uc5c5\uc744 \uc6d0\ud558\uc9c0 \uc54a\uc73c\uba74 \ud734\ub300\ud3f0\uc758 \ubc31\uc5c5 \uc124\uc815\uc5d0\uc11c \uc774 \uc5b4\ud50c\uc744 \ub04c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n- \uc6b4\uc601\uc790\ub294 \uc0dd\ub144\uc6d4\uc77c, \ud0dc\uc5b4\ub09c \uc2dc\uac01, \uc131\ubcc4, \uc774\ub984\uc774\ub098 \ubcc4\uba85\uc744 \uc11c\ubc84\ub85c \ubc1b\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n- \uacc4\uc0b0 \uacb0\uacfc\uc640 \uc784\uc758 \ubc88\ud638\ub9cc\uc73c\ub85c\ub294 \uc774\uc6a9\uc790\ub97c \uc54c\uc544\ubcfc \uc218 \uc5c6\ub3c4\ub85d \uc124\uacc4\ud588\uc2b5\ub2c8\ub2e4.\n- [2\ub2e8\uacc4\ubd80\ud130] \ucd08\ub300\ub97c \uc4f0\ub294 \ub3d9\uc548\uc5d0\ub294 \ub450 \uc0ac\ub78c\uc758 \ubcc4\uba85\uacfc \uacc4\uc0b0\uc5d0 \uc4f0\uc774\ub294 \uac12(\ubcc4\uc790\ub9ac, \ub0a0 \uae30\ub465, \ub2ec \uae30\ub465\uc758 \uc9c0\uc9c0, \ud608\uc561\ud615, \uc131\uaca9 \uc720\ud615)\uc744 \uc11c\ubc84\uc5d0 \ubcf4\uad00\ud569\ub2c8\ub2e4. \uc0dd\ub144\uc6d4\uc77c\uacfc \ud0dc\uc5b4\ub09c \uc2dc\uac01\uc740 \ubcf4\uad00\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n- [3\ub2e8\uacc4\ubd80\ud130] \uac00\uc785\ud55c \uc774\uc6a9\uc790\uc758 \ubcf8\uc778 \uc815\ubcf4\uc640 \ubcf8 \ud480\uc774, \uc774\uc6a9\uc790\uac00 \ub123\uc740 \uc0c1\ub300\uc758 \ubcc4\uba85\uacfc \uacc4\uc0b0 \uac12\uc744 \uc11c\ubc84\uc5d0 \ubcf4\uad00\ud569\ub2c8\ub2e4. \uc0c1\ub300\uc758 \uc0dd\ub144\uc6d4\uc77c\uacfc \ud0dc\uc5b4\ub09c \uc2dc\uac01\uc740 \uc5b4\ub290 \uacbd\uc6b0\uc5d0\ub3c4 \uc11c\ubc84\uc5d0 \ubcf4\uad00\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\n## \uc81c2\uc870 \ubcf4\uc720 \uae30\uac04\uacfc \ud30c\uae30\n\n| \uc815\ubcf4 | \ubcf4\uc720 \uae30\uac04 |\n|---|---|\n| \uae30\uae30\uc5d0 \uc800\uc7a5\ud55c \uc815\ubcf4 | \uc774\uc6a9\uc790\uac00 \uc9c0\uc6b0\uac70\ub098 \uc5b4\ud50c(\uc6f9\uc758 \uacbd\uc6b0 \ube0c\ub77c\uc6b0\uc800 \uae30\ub85d)\uc744 \uc9c0\uc6b8 \ub54c\uae4c\uc9c0 |\n| \ucd1d\ud3c9 \uae00 | \uac19\uc740 \uacc4\uc0b0 \uacb0\uacfc\uc5d0 \ub2e4\uc2dc \uc4f0\uae30 \uc704\ud574 \ubcf4\uad00(\uc774\uc6a9\uc790\uc640 \uc774\uc5b4\uc9c0\uc9c0 \uc54a\uc74c) |\n| \uc784\uc758 \ubc88\ud638\uc640 \uc774\uc6a9 \ud69f\uc218 \uae30\ub85d | [30\uc77c](\uac00\uc548) \ub4a4 \ud30c\uae30 |\n| \uc5f0 \ud480\uc774\uc758 \uc774\ub984 \uae30\ub85d | [30\uc77c](\uac00\uc548) \ub4a4 \ud30c\uae30 |\n\n- [2\ub2e8\uacc4\ubd80\ud130] \ucd08\ub300 \uc815\ubcf4\ub294 \ubc1b\uc740 \uc0ac\ub78c\uc774 \ub4e4\uc5b4\uc624\uae30 \uc804\uae4c\uc9c0 [30\uc77c], \uc774\uc5b4\uc9c4 \ub4a4\uc5d0\ub294 \uc5b4\ub290 \ud55c\ucabd\uc774 \ub04a\uc744 \ub54c\uae4c\uc9c0 \ubcf4\uad00\ud558\uace0, \ub04a\uc73c\uba74 \ubc14\ub85c \ud30c\uae30\ud569\ub2c8\ub2e4.\n- \ud30c\uae30\ud560 \ub54c\ub294 \ub2e4\uc2dc \uc0b4\ub9b4 \uc218 \uc5c6\ub294 \ubc29\ubc95\uc73c\ub85c \uc9c0\uc6c1\ub2c8\ub2e4.\n\n## \uc81c3\uc870 \uac1c\uc778\uc815\ubcf4\uc758 \uc81c3\uc790 \uc81c\uacf5\n\n\uc6b4\uc601\uc790\ub294 \uc774\uc6a9\uc790\uc758 \uac1c\uc778\uc815\ubcf4\ub97c \uc81c3\uc790\uc5d0\uac8c \uc81c\uacf5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\n## \uc81c4\uc870 \ucc98\ub9ac \uc704\ud0c1\n\n| \ubc1b\ub294 \uacf3 | \ub9e1\uae30\ub294 \uc77c |\n|---|---|\n| [\uc11c\ubc84 \uc5c5\uccb4 \uc774\ub984] | \uc11c\ubc84 \uc6b4\uc601, \ucd1d\ud3c9 \uae00\uacfc \uc774\uc6a9 \ud69f\uc218\uc758 \ubcf4\uad00 |\n| [\uc778\uacf5\uc9c0\ub2a5 \uc0ac\uc5c5\uc790 \uc774\ub984] | \uacc4\uc0b0 \uacb0\uacfc\ub97c \ubc14\ud0d5\uc73c\ub85c \ud55c \ucd1d\ud3c9 \uae00\uc758 \uc791\uc131 |\n\n## \uc81c5\uc870 \uad6d\uc678 \uc774\uc804\n\n\ucd1d\ud3c9 \uae00\uc758 \uc791\uc131\uc744 \uc704\ud574 \ub2e4\uc74c\uacfc \uac19\uc774 \uad6d\uc678\ub85c \uc815\ubcf4\ub97c \ubcf4\ub0c5\ub2c8\ub2e4. \uc774\uc6a9\uc790\ub294 \ub3d9\uc758\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\uace0, \ub3d9\uc758\ud558\uc9c0 \uc54a\uc544\ub3c4 \ucd1d\ud3c9\uc744 \ube80 \ud480\uc774\ub294 \ubaa8\ub450 \uc774\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n| \ud56d\ubaa9 | \ub0b4\uc6a9 |\n|---|---|\n| \ubcf4\ub0b4\ub294 \ud56d\ubaa9 | \uacc4\uc0b0 \uacb0\uacfc(\uc601\uc5ed\ub9c8\ub2e4\uc758 \ud310\uc815 \uac12, \uad00\uacc4 \uc720\ud615 \uc774\ub984, \ubbf8\ub9ac \uc4f4 \uae00). \uc0dd\ub144\uc6d4\uc77c, \uc774\ub984, \ubcc4\uba85\uc740 \ubcf4\ub0b4\uc9c0 \uc54a\uc74c |\n| \ubc1b\ub294 \ub098\ub77c, \ub54c, \ubc29\ubc95 | [\ubbf8\uad6d], \ucd1d\ud3c9\uc744 \ucc98\uc74c \ub9cc\ub4e4 \ub54c, \uc554\ud638\ud654\ub41c \ud1b5\uc2e0\uc73c\ub85c \uc804\uc1a1 |\n| \ubc1b\ub294 \uc790\uc640 \uc5f0\ub77d\ucc98 | [\uc778\uacf5\uc9c0\ub2a5 \uc0ac\uc5c5\uc790 \uc774\ub984, \uc5f0\ub77d\ucc98] |\n| \ubc1b\ub294 \uc790\uc758 \ubaa9\uc801\uacfc \ubcf4\uc720 \uae30\uac04 | \ucd1d\ud3c9 \uae00\uc758 \uc791\uc131. \ubcf4\uc720 \uae30\uac04\uc740 [\uc0ac\uc5c5\uc790 \uc57d\uad00\uc5d0 \ub530\ub978 \uae30\uac04](\ud655\uc778 \ud544\uc694) |\n| \uac70\ubd80 \ubc29\ubc95\uacfc \ud6a8\uacfc | \ub3d9\uc758 \ud654\uba74 \ub610\ub294 \u2018\ub354 \ubcf4\uae30 > \ub0b4 \uc815\ubcf4\u2019\uc5d0\uc11c \uac70\ubd80. \uac70\ubd80\ud558\uba74 \ucd1d\ud3c9\uc774 \ub098\uc624\uc9c0 \uc54a\uc74c |\n\n\uc778\uacf5\uc9c0\ub2a5 \uc0ac\uc5c5\uc790\uac00 \ubc1b\uc740 \ub0b4\uc6a9\uc744 \ud559\uc2b5\uc5d0 \uc4f0\ub294\uc9c0\uc640 \ubcf4\uad00 \uae30\uac04\uc740 [\uc0ac\uc5c5\uc790 \uc57d\uad00 \ud655\uc778 \ud6c4 \uc801\uc74c].\n\n## \uc81c6\uc870 \uc774\uc6a9\uc790\uc758 \uad8c\ub9ac\uc640 \ud589\uc0ac \ubc29\ubc95\n\n- \uc774\uc6a9\uc790\ub294 \uc5b8\uc81c\ub4e0 \uae30\uae30\uc758 \uc815\ubcf4\ub97c \ubcf4\uac70\ub098 \uace0\uce58\uac70\ub098 \uc9c0\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4(\u2018\ub354 \ubcf4\uae30 > \ub0b4 \uc815\ubcf4\u2019, \u2018\uae30\ub85d \uc9c0\uc6b0\uae30\u2019).\n- \uc774\uc6a9\uc790\ub294 \uac1c\uc778\uc815\ubcf4\uc758 \uc5f4\ub78c, \uc815\uc815, \uc0ad\uc81c, \ucc98\ub9ac \uc815\uc9c0\ub97c \uc694\uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc6b4\uc601\uc790\ub294 \uc9c0\uccb4 \uc5c6\uc774 \ucc98\ub9ac\ud569\ub2c8\ub2e4.\n- \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc774\uc6a9\uc790\uc758 \uc815\ubcf4\ub97c \ub123\uc5c8\ub2e4\uace0 \uc0dd\uac01\ub418\uba74 \ubb38\uc758 \ucc3d\uad6c\ub85c \uc54c\ub824 \uc8fc\uc138\uc694. 1\ub2e8\uacc4\uc5d0\uc11c\ub294 \uc6b4\uc601\uc790\uac00 \uadf8 \uc815\ubcf4\ub97c \ubc1b\uc9c0 \uc54a\uc73c\ubbc0\ub85c, \uc815\ubcf4\ub97c \ub123\uc740 \uc0ac\ub78c\uc758 \uae30\uae30\uc5d0\ub9cc \uc788\ub2e4\ub294 \uac83\uc744 \uc548\ub0b4\ud569\ub2c8\ub2e4. [2\ub2e8\uacc4\ubd80\ud130] \ucd08\ub300 \ub9c1\ud06c\ub97c \ubc1b\uc740 \uc0ac\ub78c\uc740 \uadf8 \ub9c1\ud06c\uc5d0\uc11c \ubcf4\ub0b8 \uc0ac\ub78c\uc774 \ub123\uc5b4 \ub454 \uc790\uc2e0\uc758 \uc815\ubcf4\ub97c \ubc14\ub85c \uc9c0\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\n## \uc81c7\uc870 \ub9cc 14\uc138 \ubbf8\ub9cc\n\n\uc5b4\ud50c\uc740 \ub9cc 14\uc138 \ubbf8\ub9cc\uc5d0\uac8c \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc0dd\ub144\uc6d4\uc77c\ub85c \ub9cc 14\uc138 \ubbf8\ub9cc\uc73c\ub85c \ud655\uc778\ub418\uba74 \uc815\ubcf4\ub97c \uc800\uc7a5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\n## \uc81c8\uc870 \uc790\ub3d9\uc73c\ub85c \uc218\uc9d1\ud558\ub294 \uc7a5\uce58\n\n- \uc6f9\uc5d0\uc11c\ub294 \uc815\ubcf4\ub97c \uc774\uc6a9\uc790\uc758 \uae30\uae30\uc5d0 \uc800\uc7a5\ud558\uae30 \uc704\ud574 \ube0c\ub77c\uc6b0\uc800 \uc800\uc7a5 \uacf5\uac04\uc744 \uc501\ub2c8\ub2e4. \uc774\uc6a9\uc790\ub294 \ube0c\ub77c\uc6b0\uc800 \uc124\uc815\uc5d0\uc11c \uc9c0\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n- [\uc774\uc6a9 \ubd84\uc11d \ub3c4\uad6c\ub97c \uc4f0\uba74 \uadf8 \uc774\ub984\uacfc \uc218\uc9d1 \ud56d\ubaa9, \uac70\ubd80 \ubc29\ubc95\uc744 \uc801\uc74c]\n\n## \uc81c9\uc870 \uc548\uc804\uc131 \ud655\ubcf4 \uc870\uce58\n\n- \uc11c\ubc84\ub85c \uac00\ub294 \ubaa8\ub4e0 \ud1b5\uc2e0\uc744 \uc554\ud638\ud654\ud569\ub2c8\ub2e4.\n- \uc11c\ubc84\uc5d0\ub294 \uc774\uc6a9\uc790\ub97c \uc54c\uc544\ubcfc \uc218 \uc5c6\ub294 \uc815\ubcf4\ub9cc \ub461\ub2c8\ub2e4(1\ub2e8\uacc4).\n- [\uc11c\ubc84 \uc811\uadfc \uad8c\ud55c \uad00\ub9ac, \uae30\ub85d \ubcf4\uad00 \ub4f1 \uc2e4\uc81c \uc870\uce58\ub97c \ub9cc\ub4e4 \ub54c \uc801\uc74c]\n\n## \uc81c10\uc870 \uc778\uacf5\uc9c0\ub2a5\uc758 \uc774\uc6a9\n\n\uc5b4\ud50c\uc740 \ucd1d\ud3c9 \uae00\uc744 \uc4f0\ub294 \ub370 \uc0dd\uc131\ud615 \uc778\uacf5\uc9c0\ub2a5\uc744 \uc501\ub2c8\ub2e4. \uc778\uacf5\uc9c0\ub2a5\uc774 \uc4f4 \uae00\uc5d0\ub294 \uadf8 \uc0ac\uc2e4\uc744 \ud45c\uc2dc\ud569\ub2c8\ub2e4. \ub9de\ub294 \uc815\ub3c4, \uad00\uacc4 \uc720\ud615 \uc774\ub984 \uac19\uc740 \uacc4\uc0b0 \uacb0\uacfc\ub294 \uc815\ud574\uc9c4 \uaddc\uce59\uc73c\ub85c \uc815\ud558\uba70 \uc778\uacf5\uc9c0\ub2a5\uc774 \uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\n## \uc81c11\uc870 \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ucc45\uc784\uc790\n\n- \uc774\ub984: [\uc774\ub984]\n- \uc5f0\ub77d\ucc98: [\uc774\uba54\uc77c]\n\n\uac1c\uc778\uc815\ubcf4 \uce68\ud574\uc5d0 \uad00\ud55c \uc2e0\uace0\ub098 \uc0c1\ub2f4\uc740 \uac1c\uc778\uc815\ubcf4\uce68\ud574\uc2e0\uace0\uc13c\ud130(\uad6d\ubc88 \uc5c6\uc774 118), \uac1c\uc778\uc815\ubcf4\ubd84\uc7c1\uc870\uc815\uc704\uc6d0\ud68c(1833-6972) \ub4f1\uc5d0 \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. [\uae30\uad00 \uc5f0\ub77d\ucc98\ub294 \uc2dc\ud589 \uc804\uc5d0 \ub2e4\uc2dc \ud655\uc778]\n\n## \uc81c12\uc870 \ucc98\ub9ac\ubc29\uce68\uc758 \ubcc0\uacbd\n\n\uc774 \ucc98\ub9ac\ubc29\uce68\uc740 [\uc2dc\ud589\uc77c]\ubd80\ud130 \uc801\uc6a9\ud569\ub2c8\ub2e4. \ub0b4\uc6a9\uc774 \ubc14\ub00c\uba74 \uc2dc\ud589 7\uc77c \uc804\ubd80\ud130 \uc5b4\ud50c \uc548\uc5d0 \uc54c\ub9bd\ub2c8\ub2e4."}}},884,[]);
